namespace ONEbook.UM.Transport
{
    using System;
    using System.Web;
    using Configurations;
    using Helpers;
    using RestSharp;
    using RestSharp.Authenticators;

    public class UMAuthenticator : IAuthenticator
    {
        private readonly UMClientConfiguration configuration;
        private readonly IPHelper ipHelper;

        public UMAuthenticator() : this(null, null)
        {
        }

        public UMAuthenticator(UMClientConfiguration configuration, IPHelper ipHelper)
        {
            this.configuration = configuration ?? UMClientManager.UMClientConfigs;
            this.ipHelper = ipHelper ?? new IPHelperImpl();
        }

        public void Authenticate(IRestClient client, IRestRequest request)
        {
            if (client == null)
            {
                throw new ArgumentNullException(nameof(client), "Rest Client cannot be null");
            }

            if (request == null)
            {
                throw new ArgumentNullException(nameof(request), "Rest Request cannot be null");
            }

            var requestUri = HttpUtility.UrlEncode(client.BuildUri(request).OriginalString.ToLowerInvariant());
            var requestHttpMethod = request.Method.ToString();
            var authHeader =
                HttpClientHelper.GenerateAuthorizationHeader(configuration, requestUri, requestHttpMethod, ipHelper.GetMachineIP());

            request.AddParameter("Authorization", authHeader, ParameterType.HttpHeader);
        }
    }
}